def celsius_til(temp, enhet="fahrenheit"):
    if enhet == "fahrenheit":
        return temp * 9 / 5 + 32
    elif enhet == "kelvin":
        return temp + 273.15

print(celsius_til(100))           # 212.0
print(celsius_til(0, "kelvin"))   # 273.15
